import fs from 'node:fs/promises';
import { parseArgs } from 'node:util';
import { chromium } from '/home/wsl/repo/rsmb.tv/node_modules/@playwright/test/index.mjs';

const {values}=parseArgs({options:{label:{type:'string'},revision:{type:'string'},out:{type:'string'},samples:{type:'string',default:'10'},matrix:{type:'string',default:'before'},hover:{type:'string',default:'1000'},journey:{type:'string'},base:{type:'string',default:'https://www.rsmb.tv'}}});
const samples=Number(values.samples);
const dwell=Number(values.hover);
if(!Number.isFinite(dwell)||dwell<0||dwell>3000)throw new Error('Invalid hover dwell');
if(!values.label||!values.revision||!values.out||!Number.isInteger(samples)||samples<1||samples>10)throw new Error('Invalid measurement options');
const base=new URL(values.base).origin;
const journeys={about:{from:'/projects',to:'/about'},flights:{from:'/projects/flights',to:'/projects/flights/map'}};
const cases=values.matrix==='after'?[{name:'rapid',hover:0,blocked:false},{name:'hover-control',hover:dwell,blocked:true},{name:'hover-prefetch',hover:dwell,blocked:false}]:[{name:'rapid',hover:0,blocked:false},{name:'hover',hover:1000,blocked:false}];
const browser=await chromium.launch();
const report={measurementVersion:2,label:values.label,expectedRevision:values.revision,measuredAt:new Date().toISOString(),conditions:{browser:browser.version(),base,viewport:'1280x900',reducedMotion:'reduce',cpuSlowdown:4,latencyMs:100,downloadMbps:10,uploadMbps:1,samples,cache:'fresh context and disabled HTTP cache',activation:'CDP native mouse press/release with an explicit timestamp; input-to-ready includes dispatch and input queue delay',control:'hover-control sets JavaScript navigator.connection.saveData=true. No server flag or HTTP Save-Data header changes. Other requests use real hosting and data.',analytics:'Umami domains blocked',notes:'Readiness is timestamped inside the browser on the second animation frame after the destination condition first matches. The detector starts at trusted pointerdown; test-runner polling does not affect this timestamp. Laboratory measurements on the deployed site, not field percentiles.'},results:[]};
const safeUrl=url=>{const u=new URL(url);return u.origin+u.pathname;};
async function identity(context){const response=await context.request.get(`${base}/deployment.json`,{headers:{'cache-control':'no-cache'}});if(!response.ok())throw new Error(`Deployment identity HTTP ${response.status()}`);const result=await response.json();if(result.commitId!==values.revision)throw new Error(`Deployment changed: expected ${values.revision}, found ${result.commitId}`);return result;}
async function persist(){await fs.writeFile(values.out,JSON.stringify(report,null,2)+'\n');}
try{
 for(const [journey,target] of Object.entries(journeys).filter(([name])=>!values.journey||name===values.journey))for(let sample=1;sample<=samples;sample++){
  const ordered=sample%2?cases:[...cases].reverse();
  for(const scenario of ordered){
   const context=await browser.newContext({viewport:{width:1280,height:900},reducedMotion:'reduce',serviceWorkers:'block'});
   const row={journey,scenario:scenario.name,hoverMs:scenario.hover,blocked:scenario.blocked,sample};
   try{
    row.deployment=await identity(context);
    const page=await context.newPage();page.setDefaultTimeout(30_000);
    await page.route(/^https:\/\/(?:cloud|gateway)\.umami\.is\//,route=>route.abort());
    await page.addInitScript(({blocked,journey,targetPath})=>{
     const stats={input:null,readyAt:null,conditionAt:null,tasks:[],events:[],workers:[],webgl:[],shifts:[]};window.__liveNavigation=stats;
     if(blocked)Object.defineProperty(navigator,'connection',{configurable:true,value:{saveData:true,effectiveType:navigator.connection?.effectiveType??'4g'}});
     const checkReady=()=>{
      const heading=document.querySelector('h1');
      const headingBox=heading?.getBoundingClientRect();
      const matches=location.pathname===targetPath&&(journey==='about'
       ?heading?.textContent?.trim()==='About'&&headingBox.width>0&&headingBox.height>0&&getComputedStyle(heading).visibility!=='hidden'
       :document.querySelector('.flights-globe canvas')&&/showing [1-9]\d* flights/.test(document.querySelector('[role=application]')?.getAttribute('aria-label')??'')&&![...document.querySelectorAll('div')].some(e=>e.textContent==='Loading globe...'));
      if(matches){stats.conditionAt=performance.now();requestAnimationFrame(()=>requestAnimationFrame(()=>{stats.readyAt=performance.now();}));}
      else requestAnimationFrame(checkReady);
     };
     document.addEventListener('pointerdown',event=>{if(!stats.input&&event.target instanceof Element&&event.target.closest('a')){stats.input={timeStamp:event.timeStamp,handlerAt:performance.now(),trusted:event.isTrusted};requestAnimationFrame(checkReady);}},true);
     const NativeWorker=window.Worker;window.Worker=class extends NativeWorker{constructor(...args){super(...args);stats.workers.push(performance.now());}};
     const getContext=HTMLCanvasElement.prototype.getContext;HTMLCanvasElement.prototype.getContext=function(type,...args){if(/^(webgl2?|experimental-webgl)$/.test(type))stats.webgl.push(performance.now());return Reflect.apply(getContext,this,[type,...args]);};
     if(PerformanceObserver.supportedEntryTypes.includes('longtask'))new PerformanceObserver(list=>stats.tasks.push(...list.getEntries().map(e=>({start:e.startTime,duration:e.duration})))).observe({type:'longtask',buffered:true});
     if(PerformanceObserver.supportedEntryTypes.includes('event'))new PerformanceObserver(list=>stats.events.push(...list.getEntries().map(e=>({name:e.name,start:e.startTime,delay:e.processingStart-e.startTime,duration:e.duration,id:e.interactionId})))).observe({type:'event',durationThreshold:16,buffered:true});
     if(PerformanceObserver.supportedEntryTypes.includes('layout-shift'))new PerformanceObserver(list=>stats.shifts.push(...list.getEntries().filter(e=>!e.hadRecentInput).map(e=>({start:e.startTime,value:e.value})))).observe({type:'layout-shift',buffered:true});
    },{blocked:scenario.blocked,journey,targetPath:target.to});
    const errors=[],failures=[],scripts=[],scriptResponses=[];let bytes=0,lastActivity=Date.now();const pending=new Set();
    page.on('pageerror',e=>errors.push(e.message));
    page.on('requestfailed',request=>{if(!/umami\.is/.test(request.url()))failures.push({url:safeUrl(request.url()),error:request.failure()?.errorText});});
    page.on('request',request=>{if(request.resourceType()==='script')scripts.push(safeUrl(request.url()));});
    page.on('response',response=>{if(response.request().resourceType()==='script')scriptResponses.push({url:safeUrl(response.url()),status:response.status(),encoding:response.headers()['content-encoding']??'identity',cache:response.headers()['x-cache']??null});});
    const cdp=await context.newCDPSession(page);
    cdp.on('Network.requestWillBeSent',e=>{pending.add(e.requestId);lastActivity=Date.now();});
    const finish=e=>{pending.delete(e.requestId);lastActivity=Date.now();};
    cdp.on('Network.loadingFinished',finish);cdp.on('Network.loadingFailed',finish);cdp.on('Network.dataReceived',e=>{bytes+=e.encodedDataLength;});
    await cdp.send('Network.enable');await cdp.send('Network.setCacheDisabled',{cacheDisabled:true});
    await cdp.send('Network.emulateNetworkConditions',{offline:false,latency:100,downloadThroughput:1250000,uploadThroughput:125000});await cdp.send('Emulation.setCPUThrottlingRate',{rate:4});
    await page.goto(base+target.from,{waitUntil:'load'});await page.mouse.move(1,850);
    const link=page.locator(`a[href="${target.to}"]`).first();await link.scrollIntoViewIfNeeded();
    await page.evaluate(()=>document.fonts.ready);
    await page.waitForFunction(()=>[...document.images].every(image=>{const b=image.getBoundingClientRect();return image.complete||b.top>=innerHeight||b.bottom<=0||b.width===0;}));
    const deadline=Date.now()+30_000;while(pending.size||Date.now()-lastActivity<500){if(Date.now()>deadline)throw new Error('Source requests did not settle');await new Promise(r=>setTimeout(r,50));}
    const box=await link.boundingBox();if(!box)throw new Error('Link is not visible');
    const {timeOrigin,intentStart,network,entry}=await page.evaluate(()=>({timeOrigin:performance.timeOrigin,intentStart:performance.now(),network:{saveData:navigator.connection?.saveData,effectiveType:navigator.connection?.effectiveType},entry:document.querySelector('script[type=module]')?.src}));
    row.network=network;row.entry=entry;const sourceBytes=bytes,sourceScripts=scripts.length;
    await page.mouse.move(box.x+box.width/2,box.y+box.height/2);
    if(scenario.hover)await new Promise(r=>setTimeout(r,scenario.hover));
    row.beforeClickScripts=scripts.slice(sourceScripts);row.beforeClickEncodedBytes=bytes-sourceBytes;
    const epoch=Date.now(),activation=epoch-timeOrigin;
    await Promise.all([cdp.send('Input.dispatchMouseEvent',{type:'mousePressed',x:box.x+box.width/2,y:box.y+box.height/2,button:'left',clickCount:1,timestamp:epoch/1000}),cdp.send('Input.dispatchMouseEvent',{type:'mouseReleased',x:box.x+box.width/2,y:box.y+box.height/2,button:'left',clickCount:1,timestamp:(epoch+1)/1000})]);
    const readyHandle=await page.waitForFunction(()=>window.__liveNavigation.readyAt);
    const ready=await readyHandle.jsonValue();await readyHandle.dispose();
    await page.waitForTimeout(80);
    Object.assign(row,await page.evaluate(({activation,intentStart,ready})=>{const s=window.__liveNavigation;return {conditionAt:s.conditionAt,readyAt:s.readyAt,inputToReadyMs:ready-activation,inputDelayMs:s.input?s.input.handlerAt-s.input.timeStamp:null,trustedInput:s.input?.trusted??false,timestampSkewMs:s.input?s.input.timeStamp-activation:null,webglAttemptsBeforeInput:s.webgl.filter(t=>t<activation).length,workersBeforeInput:s.workers.filter(t=>t<activation).length,intentLongTasks:s.tasks.filter(t=>t.start>=intentStart&&t.start<activation),navigationLongTasks:s.tasks.filter(t=>t.start>=activation&&t.start<=ready),inputEvents:s.events.filter(e=>e.start>=activation-5),intentLayoutShift:s.shifts.filter(e=>e.start>=intentStart&&e.start<activation).reduce((n,e)=>n+e.value,0),globeLabel:document.querySelector('[role=application]')?.getAttribute('aria-label')??null};},{activation,intentStart,ready}));
    row.totalEncodedBytes=bytes;row.afterSourceEncodedBytes=bytes-sourceBytes;row.navigationScripts=scripts.slice(sourceScripts);row.duplicateScripts=[...new Set(scripts.filter((s,i)=>scripts.indexOf(s)!==i))];row.scriptResponses=scriptResponses.slice();row.errors=errors.slice();row.failedRequests=failures.slice();
    await identity(context);
    if(!row.trustedInput||errors.length||failures.length||row.workersBeforeInput||row.webglAttemptsBeforeInput)throw new Error('Unexpected errors, untrusted input, or speculative renderer initialization');
    report.results.push(row);await persist();console.log(JSON.stringify({label:values.label,journey,scenario:scenario.name,sample,ms:Math.round(row.inputToReadyMs),inputDelay:Math.round(row.inputDelayMs),preScripts:row.beforeClickScripts.length}));
   }catch(error){row.failure=error.message;report.results.push(row);await persist();throw error;}
   finally{await context.close();}
  }
 }
}finally{await browser.close();}
